changeSet.sql:
CREATE TABLE public.user_role (
id BIGSERIAL PRIMARY KEY,
user_id BIGINT NOT NULL,
role VARCHAR(255) NOT NULL CHECK (role IN ('ADMIN','CLIENT')),
FOREIGN KEY (user_id) REFERENCES public.users(id)
);

changeSet.rollback:
ALTER TABLE public.ponto_dispensacao DROP CONSTRAINT fk_ponto_dispensacao_client;
ALTER TABLE public.ponto_dispensacao DROP COLUMN client_id;
DELETE FROM DATABASECHANGELOG WHERE ID = 'adicionar-client-id-ponto-dispensacao';

changeSet.sql:
-- Inserir Usuário Admin (se não existir) INSERT INTO public.users (name, email, login, password, birth_date, created_at, updated_at) VALUES ('Admin User', 'admin@sus.gov.br', 'admin_sus', '$2a$10$KkUrgvp0fZ8VURE6zz3gRur47uwgdCeirCdOA0xvt8oS2rPJmFXom', '1980-01-01', NOW(), NOW()) ON CONFLICT (login) DO NOTHING;
-- Inserir Role Admin INSERT INTO public.user_role (user_id, role) SELECT id, 'ADMIN' FROM public.users WHERE login = 'admin_sus' AND NOT EXISTS (SELECT 1 FROM public.user_role WHERE user_id = public.users.id AND role = 'ADMIN');
-- Inserir Client (Sistema Farmácia Central) INSERT INTO public.clients (client_id, client_secret, name, scopes) VALUES ('farmacia-central-app', '$2a$10$KkUrgvp0fZ8VURE6zz3gRur47uwgdCeirCdOA0xvt8oS2rPJmFXom', 'Sistema Farmácia Central', 'read write') ON CONFLICT (client_id) DO NOTHING;

